-- 2402 🏋️ Exercises from the book "advanced-spanish-academy-coaching-120-technical-tactical-and-conditioning-practi" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'advanced-spanish-academy-coaching-120-technical-tactical-and-conditioning-practi');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('5v1 rondo with side switching', 'rondo', 'overload', 'in_possession', 14, 14, NULL, 'David Aznar (Spanish FA youth coach)', 'Passing, use of space, keeping the ball and moving after the pass.', '6x6 yd square; five outside (two on one side, one on each other side), one defender inside.', 'Outside players keep the ball from the middle man. When a player on the doubled side passes, his partner runs to a side that has only one player.', 'Player who loses the ball swaps in as the defender.', 'Play the ball in the air.', 'Open body, receive and pass with back foot; go to 1 touch for speed.', '5v1', 6, 6, '6 x 6 yards', 5.5, 5.5, 10.0, false, false, false, NULL, 10),
  ('6v2 rondo with corner-middle swaps', 'rondo', 'overload', 'in_possession', 15, 15, NULL, 'David Aznar (Spanish FA youth coach)', 'Passing and keeping the ball while switching positions.', '10x20 yd box; a player on each corner and one at each long-side middle cone (6 outside), 2 defenders inside.', 'Outside six keep the ball from the two inside. Whenever a corner player passes, he swaps places with the nearby middle player.', 'Corner players 2 touches, middle players 1 touch. Defenders get out by touching the ball (1 or both of them must touch, by difficulty).', NULL, 'Talk (voice and eyes) when swapping; accurate passes into fixed spots; the two defenders press together and shut lanes.', '6v2', 8, 8, '10 x 20 yards', 18.3, 9.1, 10.0, false, false, false, NULL, 20),
  ('6v3 passing square rondo', 'rondo', 'overload', 'in_possession', 16, 16, NULL, 'David Aznar (Spanish FA youth coach)', 'Passing, use of space, keeping the ball and moving.', '15 yd square; 6 outside spread round the square, 3 defenders inside.', 'Outside players keep possession while the three inside try to win it. Rotate defenders one at a time or all three together.', 'Outside 2 touches. Harder: coach names who the ball must go to, or defenders must touch it 3 times before swapping out.', 'All players 1 touch.', NULL, '6v3', 9, 9, '15 x 15 yards', 13.7, 13.7, 10.0, false, false, false, NULL, 30),
  ('4(+2)v2 support play rondo', 'rondo', 'overload', 'in_possession', 17, 17, NULL, 'David Aznar (Spanish FA youth coach)', 'Passing, use of space, movement and supporting angles.', '8 yd square; 4 outside (one per side), 2 holding midfielders inside, 2 markers inside; everyone in pairs.', 'Outside players and the two holders keep the ball from the two markers.', 'Team in possession max 3 touches. If a marker touches the ball, the pair that lost it become markers, the markers become holders and the holders go outside.', NULL, 'Holders find good angles and distances; open up and receive on the back foot.', '4+2v2', 8, 8, '8 x 8 yards', 7.3, 7.3, 15.0, false, false, false, NULL, 40),
  ('8v4 passing square rondo', 'rondo', 'overload', 'in_possession', 18, 18, NULL, 'David Aznar (Spanish FA youth coach)', 'Passing, awareness of space, keeping the ball and moving.', '20 yd square; 2 players on each side outside, 4 defenders inside.', 'Outside eight keep the ball from the four inside.', '2 touches; no pass to the player on your own side. Defenders must touch the ball 1, 2 or 3 times to get out. Rotate singly, in pairs or fours.', NULL, 'Open body, back-foot receive; 1 touch for speed.', '8v4', 12, 12, '20 x 20 yards', 18.3, 18.3, 12.0, false, false, false, NULL, 50),
  ('Four pairs competitive keep-ball', 'rondo', 'overload', 'in_possession', 19, 19, NULL, 'David Aznar (Spanish FA youth coach)', 'Passing, awareness and movement in a competitive keep-ball.', '10 yd square; four teams of two: two pairs outside, two pairs inside (one keeping, one defending).', 'One inside pair keeps the ball with the two outside pairs; the other inside pair tries to win it. Coach counts how often each pair wins the ball off the others in a set time, or times how long each takes to win it a set number of times.', 'Outside 1 touch, inside 2 touches.', NULL, 'Play it as a real competition at high tempo; inside players check away from their marker before receiving.', '4 pairs (8)', 8, 8, '10 x 10 yards', 9.1, 9.1, 15.0, false, false, false, NULL, 60),
  ('3-team vision rondo with holding mid', 'rondo', 'overload', 'in_possession', 20, 20, NULL, 'David Aznar (Spanish FA youth coach)', 'Vision and awareness while passing, keeping the ball and moving.', '10x20 yd box; two teams of 3 outside (two on each long side, one on each short side), a holding midfielder inside plus 3 defenders.', 'Outside players and the holding mid keep the ball from the three defenders. When a player on a two-player side passes, one of them moves to a one-player side.', 'Defender who wins the ball swaps with the player who lost it. Rotate the holder so all get a turn.', NULL, NULL, '6+1v3', 10, 10, '10 x 20 yards', 18.3, 9.1, 10.0, false, false, false, NULL, 70),
  ('10v5 two-zone transition keep-ball', 'transition', 'overload', 'to_attack', 22, 22, NULL, 'David Aznar (Spanish FA youth coach)', 'Team possession and quick switching between attack and defence.', '40x40 yd split into two zones; team A (10) in one zone, team B split 5 and 5 between the zones.', 'Ten keep the ball from five. When the five win it, they pass to their five in the other zone and the whole team moves over to keep the ball there; five of the other team then cross to win it back.', 'Possession team 2 touches; the pass across is free touches. Nobody may move across until a teammate in the far zone has touched the ball.', NULL, 'Five defenders press as a unit (one on the ball, others mark or block passes); on winning it sprint across to support.', '10v5 (20 players)', 20, 20, '40 x 40 yards', 36.6, 36.6, 15.0, false, false, false, NULL, 80),
  ('6v6 keep-ball then 6v4 fast attack', 'transition', 'overload', 'in_possession', 23, 23, NULL, 'David Aznar (Spanish FA youth coach)', 'Passing and keep-ball then fast attacks in 6v4, plus recovery runs.', '40x40 yd central zone of a full pitch with goals and keepers at both ends; 6v6 inside, each team has 4 more players outside the zone.', 'After 6 passes (using their 4 outside) the six attack the far goal against the opponents'' 4 outside players (6v4). When the attack ends the opposing keeper plays into the central zone and they do the same the other way; the six attackers must sprint back.', 'The 4 outside defenders may not enter the penalty area.', NULL, 'Look to pass in behind and run into the box; react and regroup fast after attacking.', '6v6 + 4 per team + 2 GKs', 22, 22, '40 x 40 yards centre zone', 36.6, 36.6, 15.0, true, true, true, NULL, 90),
  ('Aerial passing four-zone game', 'technical', 'opposed', 'in_possession', 24, 24, NULL, 'David Aznar (Spanish FA youth coach)', 'Lofted passing, runs in behind and first-touch control of a high ball.', '70x70 yd split into 4 zones (central zones 20x40, outer zones 15x40); 8v8.', 'Team in possession sits in two zones and tries to chip a pass over a zone to a teammate running into an empty zone; he must control before it lands and pass at once inside that zone for a goal. Then everyone shifts so all players are in two zones again and they aim for the next zone.', NULL, NULL, 'Accuracy, height and weight of the lofted ball; control with whatever body part fits (head, chest, thigh, foot).', '8v8', 16, 16, '70 x 70 yards', 64.0, 64.0, 20.0, false, false, true, NULL, 100),
  ('10v10 four corner-box keep-ball', 'positional_game', 'opposed', 'in_possession', 25, 25, NULL, 'David Aznar (Spanish FA youth coach)', 'Keeping the ball and passing/receiving in tight spaces.', 'Half a pitch with a 10x10 yd box in each corner; 10v10.', 'Score by receiving a pass on the move inside each of the four corner boxes.', '2 touches. No waiting static in a box; boxes cannot be defended from inside, but the team on the ball can keep using boxes it has already scored in.', NULL, 'Keep moving to make space; check away before receiving; weight and time passes into the boxes for the run.', '10v10', 20, 20, 'Half pitch, 10 x 10 yard corner boxes', NULL, NULL, 20.0, false, false, true, NULL, 110),
  ('10v10 plus four corner neutrals', 'positional_game', 'overload', 'in_possession', 26, 26, NULL, 'David Aznar (Spanish FA youth coach)', 'Vision, awareness, decisions and support movement in possession.', 'Area between the two penalty boxes; 10v10 with a neutral player in each 10x10 yd corner zone.', 'Score by passing to a corner neutral who plays it back to a teammate; then try the same at each of the other corners.', 'Team players 3 touches, neutrals 1 touch.', NULL, 'Quick decisions under pressure; when a neutral has it, offer angled support left and right for a first-time pass; go to 2 touches to speed up.', '10v10+4', 24, 24, 'Between the penalty areas', NULL, NULL, 20.0, false, false, true, NULL, 120),
  ('10v10 timed attack on four central goals', 'finishing', 'opposed', 'in_possession', 27, 27, NULL, 'David Aznar (Spanish FA youth coach)', 'Keeping the ball and finishing quickly.', 'Area between the two penalty boxes; 4 small goals in the centre circle guarded by 2 keepers; 10v10.', 'One team scores as many as it can in a set time (e.g. 2 minutes) while the other defends; if the defenders win it, they just keep the ball for the rest of the time.', 'Nobody but the keepers enters the centre circle. A keeper''s save goes to the defending team.', NULL, 'Shoot whenever there is a yard of space; fast, accurate passes to find a shot; defenders balance guarding goals against winning the ball.', '10v10 + 2 GKs', 22, 22, 'Between the penalty areas', NULL, NULL, 20.0, true, true, true, NULL, 130),
  ('Zone keep-ball scoring one-twos with neutrals', 'possession', 'overload', 'in_possession', 28, 28, NULL, 'David Aznar (Spanish FA youth coach)', 'Keeping the ball with focus on support and passing/receiving.', 'Half a pitch with a marked zone; two teams inside plus 2 outside neutrals (title says 8v8+2, text says 9v9 inside).', 'Team in possession scores by playing a one-two with both neutrals without the opponents touching the ball.', 'Inside players unlimited touches, neutrals 2 touches and play with the team on the ball.', NULL, 'Right angles and distances in support; two players always offering left and right of the neutral; keep moving when trying to receive.', '8v8+2 (or 9v9+2)', 18, 20, 'Half pitch', NULL, NULL, 15.0, false, false, false, NULL, 140),
  ('7v9 keep-ball then transition', 'transition', 'opposed', 'in_possession', 29, 29, NULL, 'David Aznar (Spanish FA youth coach)', 'Keeping the ball when outnumbered and reacting fast in transition.', 'Full pitch, two teams of 9; the team on the ball has 7 in one half against all 9 opponents, its other 2 wait in the other half.', 'The seven must make 6 passes in a row, every player touching it, before they can pass to their 2 in the other half. If the opponents intercept, 2 of them swap with the 2 waiting players and they try the same with 7 v 9.', NULL, NULL, 'Keep moving and pass at high tempo when outnumbered; defenders press collectively around the ball.', '9v9', 18, 18, 'Full pitch', NULL, NULL, 20.0, false, false, true, NULL, 150),
  ('8v8 one-two into side zones', 'positional_game', 'opposed', 'in_possession', 30, 30, NULL, 'David Aznar (Spanish FA youth coach)', 'Passing, keeping the ball, movement and the one-two.', '60x50 yd with a coned side zone along each touchline; 8v8, both teams can attack either way.', 'Score when two players combine with a one-two that sends one through the cones into a side zone; he controls it and passes back to a teammate inside that zone.', NULL, NULL, 'Weight and timing of the return pass so the runner can take it in stride; open body and back-foot receive; 1 touch where possible.', '8v8', 16, 16, '60 x 50 yards', 54.8, 45.7, 15.0, false, false, true, NULL, 160),
  ('Three-team one-two support keep-ball', 'possession', 'overload', 'in_possession', 31, 31, NULL, 'David Aznar (Spanish FA youth coach)', 'Keeping the ball with a numerical edge, focused on support play.', '60x45 yd; three teams of 6: two inside, one spread round the outside as support for whoever has the ball.', 'A point is scored by playing one-twos with two support players on opposite sides of the area in a row without losing it. Swap which team is outside every so often.', NULL, NULL, 'Open body and back-foot receive; mix passes to feet and into space; defenders press as a compact unit.', '3 teams of 6 (12v6 effective)', 18, 18, '60 x 45 yards', 54.8, 41.1, 20.0, false, false, false, NULL, 170),
  ('7v7 one-two end-zone game', 'positional_game', 'opposed', 'in_possession', 32, 32, NULL, 'David Aznar (Spanish FA youth coach)', 'Keeping the ball with one-two combinations and movement to the flanks.', 'Half a pitch split into 3 zones: a central zone and two end zones along the sidelines; 7v7 in the centre.', 'Score by passing into an end zone for a runner, playing a one-two and keeping the ball; then repeat towards the opposite end zone.', 'Unlimited touches in the centre. Defenders may enter the box to defend; if they win it there they must clear it out of the zone with 1 touch.', 'Make it position-specific with 4-2-1 or 2-4-1 shapes, full backs or wingers running into the side zones.', 'Players must support wide teammates quickly to make the one-two.', '7v7', 14, 14, 'Half pitch', NULL, NULL, 20.0, false, false, true, NULL, 180),
  ('Three-team passing through the middle', 'positional_game', 'opposed', 'in_possession', 33, 33, NULL, 'David Aznar (Spanish FA youth coach)', 'Passing through the lines and keeping the ball with support.', 'Half a pitch split into 3 zones; three teams of 7, one per zone, the middle team defending.', 'End teams pass to each other through the middle zone while the middle team tries to intercept. Each end team may have one support player in the middle zone, rotating who goes in.', 'Change roles at any time or when the middle team wins the ball.', NULL, 'Watch the support player''s angles and distances; the middle team works together to block passing lanes.', '3 teams of 7', 21, 21, 'Half pitch', NULL, NULL, 15.0, false, false, true, NULL, 190),
  ('Four-zone 3+3v2 keep-ball and press', 'transition', 'overload', 'to_defend', 34, 34, NULL, 'David Aznar (Spanish FA youth coach)', 'Passing, keeping the ball, movement, pressing and transition.', '40x40 yd split into 4 equal zones; three teams of 6. Play starts in one zone with two teams of 3 keeping the ball against 2 defenders (3+3v2); all others move freely in the other zones.', 'After 5 passes in a row the ball goes to a teammate in another zone and everyone rushes over to make a new 3+3v2 there.', 'If the defending team wins it, they become a possession team and the team that lost it defends.', NULL, 'Quick reactions to the changing situations.', '3 teams of 6', 18, 18, '40 x 40 yards', 36.6, 36.6, 15.0, false, false, true, NULL, 200),
  ('8v8 support player square', 'possession', 'overload', 'in_possession', 35, 35, NULL, 'David Aznar (Spanish FA youth coach)', 'Keeping the ball with support movement and passing/receiving.', '25 yd square; two teams of 8: 4v4 inside, each team also has a support player on each side of the square.', 'Score by getting the ball to each of your four support players without an interception; if the defenders win it they go for the same.', NULL, NULL, 'Right angles and distances for support; open body, back-foot receive.', '8v8 (4v4+4+4)', 16, 16, '25 x 25 yards', 22.9, 22.9, 15.0, false, false, false, NULL, 210),
  ('4v4 to three goals each', 'small_sided_game', 'opposed', 'in_possession', 37, 37, NULL, 'David Aznar (Spanish FA youth coach)', 'Vision and awareness to make space and finish.', '50x60 yd with three small goals on each end line; 4v4, no keepers.', 'Teams attack and defend three goals, using the full width and length to open chances to shoot.', NULL, 'Limit touches; add neutral players.', 'Keep moving and avoid crowding the ball; check away before receiving; finish with accuracy not power (no keepers).', '4v4', 8, 8, '50 x 60 yards', 54.8, 45.7, 20.0, true, false, true, NULL, 220),
  ('5v5 four-goal game with wide outlets', 'small_sided_game', 'overload', 'to_attack', 38, 38, NULL, 'David Aznar (Spanish FA youth coach)', 'Keeping the ball and finishing using wide support and counter-attacks.', '50x60 yd with two goals at each end and four 5x30 yd side zones; 5v5 in the middle plus 2 wide players per team in the side zones.', 'One team attacks two goals using its wide players. When the defenders win the ball they pass out to a wide teammate and counter quickly.', NULL, NULL, 'Rapid transition; the player who wins it releases it fast; finish the attack quickly.', '5v5 + 2 wide each', 14, 14, '50 x 60 yards', 54.8, 45.7, 25.0, true, false, true, NULL, 230),
  ('4v3 attack through cone gates', 'phase_of_play', 'overload', 'in_possession', 39, 39, NULL, 'David Aznar (Spanish FA youth coach)', 'Final-third passing, support play and finishing.', 'Half a pitch with 4 small cone gates (5-8 yd wide) across it; 4 attackers (2 wide) v 3 defenders + keeper.', 'Attackers must pass through one gate before they can attack the goal; defenders protect the gates first, then the goal with the keeper.', 'No offside.', 'Limit touches until a gate is passed; if defenders win it they counter by dribbling over halfway.', 'Fast pace with changes of direction and lots of 2v1s; wide players stay close enough to goal.', '4v3 + GK', 8, 8, 'Half pitch', NULL, NULL, 30.0, true, true, true, NULL, 240),
  ('Continuous crossing and finishing pattern', 'finishing', 'unopposed', 'in_possession', 40, 40, NULL, 'David Aznar (Spanish FA youth coach)', 'A set pattern using wide areas to cross and finish.', 'Half pitch with a goal and keeper (diagram also shows a far goal); 8 players: 4 in the middle (B, C, D, E), 4 on the end lines, one starting with the ball as A.', 'A passes wide to B, B plays inside to C, C slips it wide for B to run onto and cross; after passing C sprints into the box with D and E to attack the cross. Rotate, then go again at once from another corner with a new A.', NULL, 'Start unopposed then add defenders; try other combinations and techniques; limit touches and make it a two-team competition.', 'Keep it flowing at tempo; keep moving rather than waiting for the cross.', '8 + GK', 8, 9, 'Half pitch', NULL, NULL, 25.0, true, true, true, NULL, 250),
  ('3+1v3 passes in behind', 'finishing', 'opposed', 'in_possession', 41, 41, NULL, 'David Aznar (Spanish FA youth coach)', 'Forward runs, losing a marker and passing in behind.', 'Two cones make a line across the pitch 5 yd longer than the penalty box width; 3 attackers plus a neutral v 3 defenders, goal with keeper.', 'Neutral starts with the ball behind the line and plays in behind the defenders; the three attackers time runs in behind and score.', 'Offside applies. Change roles often.', 'Two teams of 3 compete.', 'Defenders mark man to man; never stand still; time runs for the pass.', '3+1v3 + GK', 8, 8, NULL, NULL, NULL, 20.0, true, true, true, NULL, 260),
  ('6v6 man-marking combination game', 'small_sided_game', 'overload', 'in_possession', 42, 42, NULL, 'David Aznar (Spanish FA youth coach)', 'Short combinations followed by a quick finish with support players.', '30x35 yd; two teams of 6 plus 2 keepers; 4v4 inside in diamond shapes, each team has 2 support players on the touchline either side of the goal they attack.', 'Play short combinations and finish fast; everyone marks man to man so players must lose their marker and outrun him.', 'Outside players 1 touch.', 'Limit touches for inside players.', NULL, '6v6 + 2 GKs', 14, 14, '30 x 35 yards', 32.0, 27.4, 25.0, true, true, true, NULL, 270),
  ('3v3 three-zone escape and finish', 'finishing', 'opposed', 'in_possession', 43, 43, NULL, 'David Aznar (Spanish FA youth coach)', 'Attackers losing their marker and finishing.', 'Area twice the size of the penalty box, split into 3 equal zones; 3v3 plus keepers: 2v2 in the middle zone, one player from each team in each end zone.', 'Keeper plays into the middle zone; the receiver reads teammates'' movement, chooses who to play to and the team tries to score.', 'Rotate roles so all get to finish.', 'Make it a two-team race, e.g. first to 5 goals.', 'Check away before moving into space; finish in 2 touches max (control, shoot); head over the ball, strike through its middle.', '3v3 + 2 GKs', 8, 8, 'Double penalty area', NULL, NULL, 20.0, true, true, true, NULL, 280),
  ('3v3 plus two neutrals quick finish', 'small_sided_game', 'overload', 'in_possession', 44, 44, NULL, 'David Aznar (Spanish FA youth coach)', 'Losing a marker and finishing quickly in a small game.', 'Area twice the size of the penalty box; 3v3 plus 2 neutrals with the team on the ball and 2 keepers (titled 4v4 (+2)).', 'Players look to shoot before the fourth pass, using the neutrals to make space and shooting as early as possible.', 'Shot before the 4th pass.', NULL, 'Use the extra players to create shooting space; lose your marker to receive; cut the time between first touch and pass or shot.', '3v3+2 + 2 GKs', 10, 10, 'Double penalty area', NULL, NULL, 20.0, true, true, true, NULL, 290),
  ('CBs track back, intercept, switch long', 'defending', 'opposed', 'to_attack', 52, 52, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Defenders tracking back, intercepting and playing out from the back.', 'Half to full pitch; 6 players: two red centre backs, blue opponents (one passer, one pressing forward), red wide targets in squares on each flank.', 'A blue plays a deep ball (lofted or on the ground); the two reds drop together, one intercepts and controls under pressure, carries it forward a few steps and hits a diagonal pass to the far-side wide teammate.', NULL, NULL, 'Line positioning by ball and teammates; body position while recovering; choose the direction after the interception by where the nearest opponent is; dribble and pass with the foot away from pressure.', '6', 6, 6, NULL, NULL, NULL, 20.0, false, false, true, NULL, 300),
  ('CB headed clearances to midfielders', 'defending', 'opposed', 'out_of_possession', 53, 53, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Centre backs directing headed clearances from a long ball.', '6 players: two red centre backs, red midfielders ahead, a blue server out wide and a blue forward who presses.', 'Blue plays a long ball, the reds drop together under pressure and one heads it on purpose to a midfield teammate so the team can step up.', NULL, NULL, 'Line position; awareness when tracking back; pick the right header (under the ball for height, or hang it up to give a teammate time); always face forward.', '6', 6, 6, NULL, NULL, NULL, 20.0, false, false, true, NULL, 310),
  ('CB cover and challenge on the flank', 'defending', 'opposed', 'out_of_possession', 54, 54, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Centre backs covering and challenging when the attack goes down the flank.', '4 players: two red centre backs, two blue attackers (one central with balls, one on the flank).', 'Blue plays down the line to his teammate; the reds shift across, one presses, uses his shoulder and tries to win the ball with a legal challenge. Repeat once the ball is won.', NULL, NULL, 'Line position; use the body to push the man off the ball if you cannot reach it; read the run and its path rather than the ball to intercept or pressure the receiver.', '4', 4, 4, NULL, NULL, NULL, 20.0, false, false, false, NULL, 320),
  ('Defending crosses with man-marking headers', 'set_piece', 'opposed', 'set_piece', 55, 55, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Centre backs defending set-piece balls in the air.', 'Penalty area with a goal; 5 players: a crosser on the side line, 2 red defenders, 2 blue attackers.', 'A high hanging ball is crossed in; the two defenders, each marking a man, try to head it clear while the attackers try to score.', NULL, 'Start with static headers, then have attackers move more so defenders head clear on the move.', 'Position and body shape; strong headers with the right part of the head; accept some physical contact.', '5', 5, 5, NULL, NULL, NULL, 20.0, true, false, true, NULL, 330),
  ('Defending high long balls with headers', 'defending', 'opposed', 'out_of_possession', 56, 56, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Centre backs heading away high balls under pressure.', '6 players: two crossers on the side lines, 2 red defenders near the edge of the box, 2 blue attackers.', 'Both crossers hang a high ball towards the edge of the box at the same time; each red, pressured by a blue, heads his ball clear.', NULL, NULL, 'Strong headers with good height; position and body shape; clean contact; accept physical contact.', '6', 6, 6, NULL, NULL, NULL, 20.0, false, false, false, NULL, 340),
  ('Build-up: across the back, FB long line pass', 'passing_opposed', 'passive', 'in_possession', 59, 59, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Building up from the back under pressure from opposition forwards.', 'Full pitch; keeper, reds at the back and full backs, two blue forwards pressing, red forward targets in squares in the far half.', 'Short goal kick, close control and short forward runs by the full backs, then a long ball up the line into the other half for a forward.', '2 opposition forwards press.', NULL, 'Receive with the foot away from pressure; use an arm to shield when carrying; long pass with the free foot (instep/laces), follow through balanced for distance.', 'GK + 4-5 reds v 2', 8, 10, 'Full pitch', NULL, NULL, 20.0, false, true, true, NULL, 350),
  ('Build-up: FB inside run and long diagonal', 'passing_opposed', 'passive', 'in_possession', 60, 60, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Building up from the back under pressure and switching with a long diagonal.', 'Full pitch; keeper, reds at the back and full backs, two blue forwards pressing, red targets in squares near halfway on each flank.', 'Short goal kick, close control, the full back carries a short way inside then plays a long diagonal with his weaker foot to a teammate in the opponent half.', '2 opposition forwards press.', NULL, 'Receive away from pressure; arm to shield on the carry; weaker-foot long pass: plant foot further from the ball and slow the follow-through to steer it.', 'GK + 4-5 reds v 2', 8, 10, 'Full pitch', NULL, NULL, 20.0, false, true, true, NULL, 360),
  ('Back four circulation to switch play', 'phase_of_play', 'opposed', 'in_possession', 61, 61, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Moving the ball across the back line under pressure to switch the point of attack.', 'Half pitch: goalkeeper and back four against the opposition''s front six.', 'Keeper plays a short goal kick to a full back; the back four move it across the line (one player lets the ball run past him as a dummy) to the far full back, who dribbles up the line and hits a long ball down the flank for a forward.', NULL, NULL, 'Dummy runner uses his body to steer pressure away; shield the ball between you and the presser when dribbling to the touchline; strike the long pass with your back to the opponent.', 'GK + 4 v 6', 11, 11, NULL, NULL, NULL, 20.0, true, true, true, NULL, 370),
  ('Full back receive, feint and turn', 'technical', 'unopposed', 'in_possession', 62, 62, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Base technique for full backs receiving from the keeper: short dribble, weight shift and change of direction.', 'Penalty area and wide channels; cones on each flank; keeper and two full backs.', 'Keeper plays short to a full back, who carries forward, sells one way and cuts the other past the cones, then passes back to the keeper now at the corner of the six-yard box; keeper switches to the other full back who repeats. Cut can go inside or outside.', NULL, NULL, 'Touch the ball with the laces or instep throughout.', '2 full backs + GK', 3, 3, NULL, NULL, NULL, 20.0, false, true, false, NULL, 380),
  ('Wide 1v1 options: byline or cut in', 'finishing', 'unopposed', 'in_possession', 63, 63, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Wide player''s technical actions to get a cross in for two forwards.', 'Server in the centre circle with balls; winger on the flank; two forwards in the box; keeper; cones marking a cut-in lane by the box.', 'Server passes wide to a winger who has checked away from his marker; winger either dribbles to the byline and crosses or cuts in through the cones and crosses for the two forwards to finish.', NULL, 'Add a defender coming from the side to push the winger wide and block the cross.', 'Lock the hip when crossing; pace of run sets power of the cross; cross must at least reach the near post.', 'server + winger + 2 forwards + GK', 5, 6, NULL, NULL, NULL, 20.0, true, true, true, NULL, 390),
  ('Wide 1v1 beat a frontal defender and cross', 'finishing', 'opposed', 'in_possession', 64, 64, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Beating a defender face-on on the flank before crossing.', 'As the previous wing crossing set-up, with a defender facing the winger.', 'Server plays to the winger after he checks away; winger takes on the frontal defender with a feint or dummy, then either goes to the byline and crosses or cuts in through the cones and crosses for two forwards.', NULL, NULL, 'Once past the defender, hit a mid-range cross with a long leg extension so the body weight can shift and balance is kept.', 'server + winger v 1 + 2 forwards + GK', 6, 6, NULL, NULL, NULL, 20.0, true, true, true, NULL, 400),
  ('Wide 1v1 with switch to far flank', 'one_v_one', 'opposed', 'in_possession', 65, 65, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Wide players'' movements: losing a marker, feints, explosive moves and switching play before a 1v1 and cross.', 'Half pitch with a server in the centre circle, a winger plus defender on each flank, a forward in the box and a keeper.', 'Server plays to a winger who loses his marker, controls and protects; he feints from a standstill, bursts inside and switches with a long pass to the other flank. The far winger cushions it, approaches the defender slowly, picks a foot and turns past him, then crosses to the forward or shoots with his weaker foot.', NULL, NULL, 'Make the defender retreat so the change of pace and direction catches him off balance.', 'server + 2 wingers + forward v 2 + GK', 7, 8, NULL, NULL, NULL, 20.0, true, true, true, NULL, 410),
  ('Back four shifting when ball is wide', 'defending', 'opposed', 'out_of_possession', 66, 67, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Defenders'' movements as a unit when the ball is in wide areas.', 'Half pitch: back four and keeper against four attackers including wingers.', 'Attackers move the ball across the pitch from a wide player; the back line shifts together toward the ball, the nearest defender presses to stop the pass, shows the winger outside and denies the inside pass. Ends with a cross to the forward or a weak-foot shot.', NULL, 'Change defenders'' aims to more 1v1 work on the player coming inside, with the line squeezing his space.', 'When tracking back face the touchline opponent with head half-turned to the ball; low centre of gravity when pressing; knees bent, on the toes, torso upright in 1v1.', '4v4 + GK', 9, 9, NULL, NULL, NULL, 20.0, true, true, true, NULL, 420),
  ('Tracking back, intercepting and clearing', 'defending', 'overload', 'out_of_possession', 68, 68, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Centre backs reading body signals to intercept, defend crosses and clear in a controlled way.', 'Half pitch with keeper and goal; two small goals on the halfway line; 4 attackers (2 central mids with balls, 2 wingers) against 2 centre backs.', 'A central midfielder hits a long diagonal to a winger; the two centre backs stay balanced, shift and press or intercept. Play ends with a cross or weak-foot shot; centre backs head crosses clear the other way or, after an interception, aim the clearance into a small goal.', NULL, NULL, 'Vary clearance technique with ball location: one leg, on the run, or both legs static or moving.', '4v2 + GK', 7, 7, NULL, NULL, NULL, 20.0, true, true, true, NULL, 430),
  ('Central midfielders'' support in build-up', 'passing_unopposed', 'unopposed', 'in_possession', 71, 73, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Coordinating the two central midfielders'' movements to receive facing forward when building from the back.', 'Half a full-size pitch: keeper, back four and two central midfielders.', 'Short goal kick; nearest midfielder positions behind the new ball carrier to receive on the far foot and play forward; the far midfielder runs diagonally to offer another option, or receives straight from the full back. Success = at least two passing options and receiving facing the opponent''s half.', NULL, '(2) add a forward: near midfielder lines up with the most advanced teammate after the ball goes back to a centre back, option is a pass into the forward and set back. (3) ball is moved one more time across to the second centre back before the midfielders offer new options and a lay-off from the forward.', 'Receive with the foot furthest from the potential opponent; open body so the first touch can be a pass.', 'GK + 4 defenders + 2 CMs (+1 forward)', 7, 8, NULL, NULL, NULL, 20.0, false, true, true, NULL, 440),
  ('Switching flanks through central midfield', 'passing_opposed', 'passive', 'in_possession', 74, 75, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Building up and switching the ball to the far winger via central midfield away from pressure.', 'Half pitch: keeper, back four, one central midfielder and one winger, plus one opposing midfielder.', 'Short goal kick to a full back, who passes (or plays first time) into the midfielder; the midfielder takes it away from the opponent''s side to make him turn, then hits a long switch to the far winger with the foot on the less pressured side.', NULL, '(2) add a second central midfielder: the receiver passes to him and spins round the opponent for a 1-2 before the long switch.', 'Keep balance when receiving and striking; everyone faces the opponent''s half.', 'GK + 4 + 1-2 CM + winger v 1', 8, 9, NULL, NULL, NULL, 20.0, false, true, true, NULL, 450),
  ('Centre back interception from goal kick', 'transition', 'opposed', 'to_attack', 76, 76, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Defending an opposition goal kick and launching an attack out wide.', 'Full pitch half-and-half: 2 centre backs and 2 wingers against 2 opposition forwards; opposition keeper kicks long.', 'Opposition keeper takes a goal kick; under pressure from the two forwards, one centre back controls the interception and the pair work the ball to a winger in the other half, ending with a long pass with the foot on the less pressured side.', NULL, NULL, 'Use the body part that fits the ball height for the interception; stay balanced; keep facing the attacking team so the run can be adjusted.', '4v2 + opposition GK', 7, 7, NULL, NULL, NULL, 20.0, false, true, true, NULL, 460),
  ('Headed clearances while retreating, then attack', 'transition', 'opposed', 'to_attack', 77, 77, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Adjusting position while running back to head clear, then moving quickly into attack.', 'As the goal-kick practice plus two central midfielders: 2 CBs, 2 CMs, 2 wingers against 2 forwards, keeper at the defending goal.', 'Opposition goal kick; centre backs retreat and adjust to head the ball, midfielders drop to reinforce and head forward, covering each other if beaten. An accurate headed clearance to a teammate starts an attack ending in a 1-2 or long switch to a winger.', NULL, NULL, 'Defenders and midfielders head differently; head through the middle of the ball toward a teammate; scan before contact.', '6v2 + GKs', 9, 10, NULL, NULL, NULL, 20.0, false, true, true, NULL, 470),
  ('Midfield combinations after defending a long ball', 'passing_opposed', 'opposed', 'to_attack', 78, 79, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Defending a long ball then building up through passing and movement of the two central midfielders.', 'Half to full pitch: red centre backs, two central midfielders and two wingers against blue opponents (2 forwards plus a centre back who hits the long ball); keeper.', 'A blue centre back plays long; a red centre back controls and plays short to start; one midfielder moves to offer a return while aware of his partner so the ball carrier always has two options; attack goes out wide. Three example patterns shown.', NULL, 'Example 3 adds one more winger and one more opponent.', 'Focus on pair passing and movement between the two midfielders and the receiving centre back; be ready centrally as the ball is cleared.', 'about 7v3 + GK', 10, 12, NULL, NULL, NULL, 20.0, false, true, true, NULL, 480),
  ('Front six shadow movements with mannequins', 'combination', 'unopposed', 'in_possession', 82, 83, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Coordinating forwards and midfielders with and without the ball according to ball and defender positions.', 'Half pitch with keeper; mannequins as opposition defenders and midfielders; front six (forwards, midfielders, wingers); balls at halfway.', 'First the six close down the mannequins in a semicircle; then possession is ''won'', a midfielder plays wide and the shape inverts so the wide man has two options: a diagonal ball to the near post or a 1-2 with a midfielder then a far-post cross. Ends with a forward''s shot.', NULL, '(2) forwards now combine a diagonal then a curved run through ''waiting areas'', delaying or holding to stay onside depending on the passer.', NULL, '6 + GK', 7, 7, NULL, NULL, NULL, 20.0, true, true, true, NULL, 490),
  ('Forwards'' runs for crosses: near and far post', 'finishing', 'unopposed', 'in_possession', 84, 85, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Forwards coordinating runs to two target points for a winger''s cross.', 'Penalty area and flanks: wingers with balls on each side, two forwards at the edge of the box, keeper.', 'Winger dribbles up beside the box; forward 1 runs diagonally into the middle then checks back to the near post for a short cross; forward 2 makes a short diagonal to the box edge then curves to the far post for a deep cross; one-touch finish with the right body part.', NULL, '(2) add a defender out wide: winger must hold him off; both forwards expect a near-post ball, forward 1 runs straight across, forward 2 feints to the spot then attacks the near post.', NULL, '2 wingers + 2 forwards + GK (+1 defender)', 5, 6, NULL, NULL, NULL, 20.0, true, true, true, NULL, 500),
  ('Forward diagonal run to escape marker', 'finishing', 'opposed', 'in_possession', 86, 86, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Forwards creating space to run into and finishing.', 'Edge of the box: two forwards against one defender, keeper; one forward starts deep with the ball.', 'Deep forward passes to one side of his teammate, who checks away from the marker, turns and sprints diagonally into space to receive and shoot in one or two touches with the foot on the less pressured side.', NULL, NULL, 'Keep the head turned to the ball while turning so the pass can be taken facing goal.', '2v1 + GK', 4, 4, NULL, NULL, NULL, 20.0, true, true, true, NULL, 510),
  ('Back to goal: hold off, turn and finish', 'one_v_one', 'opposed', 'in_possession', 87, 87, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Body shape to protect the ball, get round a defender and shoot.', 'Edge of the box: server with balls, forward with a defender behind him, keeper.', 'Server plays into the forward with his back to goal; he holds the defender off with his arm, turns the side the arm signals while keeping contact and his body between man and ball, then shoots.', NULL, NULL, 'Arm stays on the defender''s body to feel where he is and keep space between defender and ball.', '2v1 + GK', 4, 4, NULL, NULL, NULL, 20.0, true, true, true, NULL, 520),
  ('Shooting on the run from an angle', 'finishing', 'unopposed', 'in_possession', 88, 89, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Shooting first time or after a touch while running at an angle to goal.', 'Edge of the box: passer and runner, keeper.', 'Runner makes a diagonal run to meet a pass and shoots first time at an angle, or takes a touch away from an imaginary defender and shoots.', NULL, 'Variation: runner cuts inside with the ball and shoots with the other foot. Progression: add a defender.', 'Strike with the most suitable foot; match run speed to the pass; lower centre of gravity and plant on the non-kicking leg when changing direction.', '2 + GK', 3, 4, NULL, NULL, NULL, 20.0, true, true, true, NULL, 530),
  ('Diagonal near-post run, first-time finish', 'finishing', 'unopposed', 'in_possession', 90, 91, NULL, 'Rafa Juanes (Villarreal CF academy)', 'Finishing first time against the direction of the run, often with the weaker foot.', 'Penalty area: wide crosser near the corner, forward on the far side of the box, keeper.', 'Wide player crosses low; the forward runs diagonally toward the near post and finishes with the foot furthest from goal using the instep (or laces).', NULL, 'Add a passive defender. Variation: forward cannot shoot at once so controls with back to goal (defender, cone or mannequin), shields, turns and shoots.', 'Position the supporting leg so the kicking leg can twist; use arms to balance; shield with the body.', '2 + GK', 3, 4, NULL, NULL, NULL, 20.0, true, true, true, NULL, 540),
  ('3v2 free possession', 'possession', 'overload', 'in_possession', 100, 100, NULL, 'Manu Dorado (Real Madrid academy)', 'Passing, awareness of space, keeping the ball and movement.', 'Small coned square.', 'Three keep the ball from two with no conditions, a global game using all match factors.', NULL, NULL, 'Create passing lanes, protect the ball, control and pass quickly, press together.', '3v2', 5, 5, NULL, NULL, NULL, NULL, false, false, false, NULL, 550),
  ('3v2 to an end zone', 'positional_game', 'overload', 'in_possession', 101, 101, NULL, 'Manu Dorado (Real Madrid academy)', 'Attacking in one direction and zonal defending in a small group.', 'Rectangle with an end zone at one end and an end line at the other.', 'Reds score a point by passing to a teammate who controls inside the end zone; if the two yellows win it they score by dribbling over the opposite end line.', NULL, 'Play offside.', 'Collective tasks alone can turn into disorder; focus on zonal defending, pressing together, protecting ball and zone, when and where to attack.', '3v2', 5, 5, NULL, NULL, NULL, NULL, false, false, true, NULL, 560),
  ('Back four shifting against 6 passers', 'defending', 'overload', 'out_of_possession', 104, 104, NULL, 'Manu Dorado (Real Madrid academy)', 'Collective defending and positioning as the ball moves around.', 'Half pitch with keeper; six attackers in a 2-4 or 4-2 shape against a back four.', 'Six attackers keep switching the ball; the back four move as a unit with the ball, e.g. stepping up, then dropping and sliding to the side when play is switched.', NULL, NULL, 'Use guided questions so players own the solutions.', '6v4 + GK', 11, 11, NULL, NULL, NULL, NULL, false, true, true, NULL, 570),
  ('5v4 attack after build-up', 'phase_of_play', 'overload', 'in_possession', 108, 110, 'Practice 1', 'Manu Dorado (Real Madrid academy)', 'Build-up, decision making and attacking the final third.', 'Half pitch plus; reds in 3-2-3 (3 defenders, 2 CMs, 2 wingers, 1 forward) against 4 blue defenders and a keeper; highlighted attacking zone.', 'A red defender passes to a midfielder who dribbles forward and feeds one of the front three; then a 5v4 attack in the highlighted zone with free decisions to get behind and score.', NULL, 'Adapt to your formation (4-4-2, 4-3-3, etc.); add full backs with an overlap objective toward the byline, centre backs told to play wide quickly, extra blue wingers or midfielders; brief each position on with/without-ball roles.', 'Find the right decisions to get in behind; diagram is one example only.', '8 v 4 + GK (5v4 in zone)', 13, 17, NULL, NULL, NULL, NULL, true, true, true, NULL, 580),
  ('2v2 flank game to a line', 'one_v_one', 'opposed', 'in_possession', 111, 111, 'Practice 2', 'Manu Dorado (Real Madrid academy)', '1v1/2v2 play: passing, dribbling, attacking space and defending.', 'Area twice as long as wide with an end line.', 'Two attackers try to dribble over the line; defenders win it or kick it out. Attackers choose any combinations or moves; coach asks questions on what worked and the group practises the agreed solutions.', NULL, NULL, 'Guided discovery questions; suits wingers and full backs, attacking or defending phase.', '2v2', 4, 4, NULL, NULL, NULL, NULL, false, false, true, NULL, 590),
  ('Defensive line distances against 5 attackers', 'defending', 'overload', 'out_of_possession', 112, 112, 'Practice 3', 'Manu Dorado (Real Madrid academy)', 'Correct distances, positions and movement of the defensive line.', 'Half pitch with keeper: five attackers against four defenders.', 'Attackers pass and switch play; the four defenders move according to ball position. Coach and players discuss where to stand when opponents advance centrally or wide, then rehearse the agreed answers.', NULL, NULL, NULL, '5v4 + GK', 10, 10, NULL, NULL, NULL, NULL, false, true, true, NULL, 600),
  ('3v3 wide play small-sided game', 'small_sided_game', 'opposed', 'in_possession', 113, 113, 'Practice 4', 'Manu Dorado (Real Madrid academy)', '1v1/2v1 play, creating space, passing, receiving and movement on the flanks.', 'Two side-by-side pitches with small goals at one end and a defenders'' goal zone at the other.', 'Free 3v3 games with two wingers and one central player per team, focusing on wide attacks, numerical advantages, moves to beat and attacking space.', NULL, NULL, 'Overload wide; take the ball to the edge of your zone; get in front of the marker and protect; seek 2v1s; check away before receiving.', '3v3', 6, 12, NULL, NULL, NULL, NULL, true, false, true, NULL, 610),
  ('Football conditioning circuit, 7 stations', 'conditioning', 'unopposed', NULL, 121, 121, NULL, 'Fernando Gaspar (China National Team)', 'Builds stamina, strength, agility, speed and coordination.', 'Half pitch with 7 stations: sit-up mats, zig-zag cones, 6 hurdles, rings, a line of poles and two speed ladders.', 'Players move through the stations in set orders: sit-ups, zig-zag run, hurdle jumps, one-leg hops through rings, slalom through poles, ladder skips, sit-ups. Seven series each use a different order of stations.', 'Series 1 uses all 7 stations; later series use shorter sequences, finishing with 2 reps of stations 1-4.', NULL, 'Give enough rest between series; cut the number of series for younger groups.', NULL, NULL, NULL, 'Half a full sized pitch', NULL, NULL, 25.0, false, false, false, '14-18', 620),
  ('Continuous 1v1 duels to goals', 'one_v_one', 'opposed', NULL, 122, 122, NULL, 'Fernando Gaspar (China National Team)', 'Dribbling, beating a man and attacking/defending 1v1 while conditioning.', 'Area twice the size of a penalty box with a goal at each end; 8 players split across four corner positions A, B, C, D.', 'A dribbles into the middle and C comes out to defend in a 1v1; A tries to score. When it ends, A goes to B''s spot and C to D''s, then D dribbles out to take on B, and so on continuously.', 'Defender only defends the goal. 30 seconds rest every 2 minutes.', NULL, 'Change pace or direction to beat the defender; keep to 8 players so nobody stands waiting.', '8 players', 8, 8, 'Double the penalty area', NULL, NULL, 10.0, true, false, true, '14-18', 630),
  ('7v7 man-marking small sided game', 'small_sided_game', 'opposed', NULL, 123, 123, NULL, 'Fernando Gaspar (China National Team)', 'Aerobic endurance in a game where everyone man-marks.', 'Up to half a pitch, two goals with keepers, 6v6 outfield.', 'Normal 7v7 game but each outfield player picks one opponent to track. The coach can call a switch so players change who they mark.', 'Strict man-to-man marking.', 'Coach calls a change of marking assignments mid-game.', 'Under tight marking, protect the ball with body and arm; receive and shoot quickly.', '7v7 (6v6 + GKs)', 14, 14, 'Up to half a full sized pitch', NULL, NULL, 15.0, true, true, true, '14-18', 640),
  ('Dribble, one-two and shoot from distance', 'combination', 'unopposed', 'in_possession', 124, 124, NULL, 'Fernando Gaspar (China National Team)', 'Timing of forward runs and finishing from in and outside the box.', 'Half pitch, keeper in goal, 4 pairs of players: reds at two cone slaloms near halfway, blues as wall players on the edge of the box.', 'Red dribbles through the cones, plays a one-two with the diagonal blue, runs onto the return and shoots from outside the box. Red and blue swap roles, then the other side goes.', NULL, 'Shoot with one touch to demand a well-weighted pass.', 'Soft touches in the dribble; time the return pass so the runner does not slow down.', '8 + GK', 9, 9, 'Half a full sized pitch', NULL, NULL, 10.0, true, true, true, '14-18', 650),
  ('Football circuit ending in a shot', 'conditioning', 'unopposed', NULL, 125, 125, NULL, 'Fernando Gaspar (China National Team)', 'Strength and stamina conditioning with a finishing station.', 'Half pitch with 7 stations: mat, change-of-direction cones, 6 hurdles, rings, poles, speed ladder, and balls at the top of the box with a keeper.', 'Sit-ups, sharp direction changes, hurdle jumps, three high jumps in each ring, zig-zag through poles, ladder skips, then collect a ball, dribble round a cone and shoot.', '5 series in the same order.', NULL, 'Rest between series; fewer series for younger players.', NULL, NULL, NULL, 'Half a full sized pitch', NULL, NULL, 15.0, true, true, true, '14-18', 660),
  ('Circuit stations into overlap and cross', 'combination', 'unopposed', 'in_possession', 126, 126, NULL, 'Fernando Gaspar (China National Team)', 'Passing, combination play and timing of runs inside a conditioning circuit.', 'Half pitch, 4 areas: sit-up mat (1), speed ladder on the flank (2), hurdles (3), speed rings (4); keeper in goal.', 'Each player does his station exercise first. Player 1 passes to 2, who passes to 3; 1 curves round a cone into the box while 2 overlaps down the flank to get the ball back from 3. 3 and 4 also curve into the box and 2 crosses for one of the three to finish.', 'Station exercise before joining the combination: 5 sit-ups, ladder skips, 5 hurdle jumps, ring hops.', NULL, 'Coach coordinates the four players so passes and runs are timed.', '4 groups + GK', NULL, NULL, 'Half a full sized pitch', NULL, NULL, 15.0, true, true, true, '14-18', 670),
  ('Weights, hurdles, one-two and shoot race', 'conditioning', 'unopposed', NULL, 127, 127, NULL, 'Fernando Gaspar (China National Team)', 'Strength, explosive power and finishing.', 'Two groups on either side of half pitch with cones and hurdles; two blue servers at the top of the box; keeper in goal; 5kg weights at the start.', 'Pairs race: 10 reps with 5kg weights, zig-zag run to halfway, sprint, two standing jumps over hurdles twice, then collect a ball, dribble through cones, one-two with the blue server and shoot.', 'Competition in pairs, first to score wins a point; 4 reps per pair.', NULL, 'Jump the hurdles from standing with feet together.', '2 groups + 2 servers + GK', NULL, NULL, 'Half a full sized pitch', NULL, NULL, 10.0, true, true, true, '14-18', 680),
  ('Diagonal runs, wide pass, cross and finish', 'finishing', 'unopposed', 'in_possession', 129, 129, NULL, 'Fernando Gaspar (China National Team)', 'Acceleration, coordinated runs, crossing and finishing.', 'Half pitch, 4 starting positions, keeper in goal, yellow cones marking run channels.', 'A central player passes diagonally into the middle for a teammate making a diagonal run, who passes wide. Both central players then cross over and run through the cones to near and far post while the wide player runs through cones, receives, dribbles to the byline and crosses.', 'Second pass first time.', NULL, 'Timing of runs with passes and cross; watch for collisions on crossing runs.', '3 per rep + GK', NULL, NULL, 'Half a full sized pitch', NULL, NULL, 20.0, true, true, true, '14-18', 690),
  ('Pole skips, one-two, dribble and shoot', 'combination', 'unopposed', 'in_possession', 130, 130, NULL, 'Fernando Gaspar (China National Team)', 'Coordination, speed, one-two play, dribbling and finishing.', 'Half pitch, a line of players on each side, 4 poles on the ground, cones and cone gates, 2 blue support players at the top of the box, keeper.', 'Both sides go at once: skip over the 4 poles, one-two with a blue support player, run round 3 cones to receive the return, dribble through gates and shoot.', NULL, NULL, 'Support player''s return weighted in front of the runner; soft dribbling touches; full game speed.', '2 lines + 2 support + GK', NULL, NULL, 'Half a full sized pitch', NULL, NULL, 8.0, true, true, true, '14-18', 700),
  ('Flank one-two, run in behind and cross', 'combination', 'unopposed', 'in_possession', 131, 131, NULL, 'Fernando Gaspar (China National Team)', 'Speed, coordination and timing of short and long runs in an attacking combination.', 'Half pitch, cones and a row of poles; worked on both sides; keeper in goal.', 'Player with the ball passes wide, skips through the poles and gets a one-two back from the teammate who moved inside. He then plays into space down the flank for the teammate, runs round the last cone into the box and finishes the cross.', NULL, NULL, 'Short explosive acceleration; time the passes and cross to the runs.', 'Pairs + GK', NULL, NULL, 'Half a full sized pitch', NULL, NULL, 20.0, true, true, true, '14-18', 710),
  ('Agility circuit into 1v1 race to goal', 'one_v_one', 'opposed', NULL, 132, 132, NULL, 'Fernando Gaspar (China National Team)', 'Acceleration, agility and finishing in a 1v1.', 'Half pitch, two circuits (left: 4 hurdles and a pole; right: 2 floor poles and a cone), servers by the corners of the box, keeper.', 'On each side a red attacker and yellow defender race flat out round a circuit; the server plays into the box, the red tries to get in front to receive and shoot while the yellow closes to stop the goal.', '4 series per circuit with recovery between.', NULL, 'On turns bend the knees, drop a shoulder and push off one foot.', 'Pairs + 2 servers + GK', NULL, NULL, 'Half a full sized pitch', NULL, NULL, 10.0, true, true, true, '14-18', 720),
  ('Eyes-shut defenders 3v3 quick finish', 'one_v_one', 'opposed', 'in_possession', 133, 133, NULL, 'Fernando Gaspar (China National Team)', 'Speed of play and quick decisions attacking and defending a 3v3.', 'Half pitch, keeper in goal, 3 blue defenders in the box with eyes shut, 3 red attackers facing them, coach with balls near the centre circle.', 'Coach shouts GO and passes to one attacker; defenders open their eyes and react while the attackers try to score inside 4 seconds. If not, restart from the coach.', '4 seconds to score; swap roles halfway (after 3.5 minutes).', NULL, 'Attackers free to choose any way to score; give rest between attacks.', '3v3 + GK', 7, 7, 'Half a full sized pitch', NULL, NULL, 7.0, true, true, true, '14-18', 730),
  ('3v2 keep-ball into fast break', 'transition', 'overload', 'in_possession', 134, 134, NULL, 'Fernando Gaspar (China National Team)', 'Speed of play and quick decisions exploiting a 3v2.', 'Half pitch split into 2 zones, each with 3 reds v 2 blues; keeper in goal; coach in the middle.', 'Reds keep the ball against the 2 defenders in their zone; on the coach''s call the numbered zone breaks quickly to score past the keeper using the extra player.', '10 repetitions with recovery; swap roles halfway.', 'Split into 2 competing teams, most goals wins.', 'Let players decide how to attack; only stop to review after a goal.', '2 x 3v2 + GK', 11, 11, 'Half a full sized pitch', NULL, NULL, 15.0, true, true, true, '14-18', 740),
  ('Race for coach''s ball, 1v1 to goal', 'one_v_one', 'opposed', NULL, 135, 135, NULL, 'Fernando Gaspar (China National Team)', 'Acceleration, shielding the ball and finishing in a 1v1.', 'Half pitch with 5 marked starting positions around the box edge; keeper in goal; coach between the two players.', 'Coach throws or passes the ball out in front; both race for it. The winner shields and tries to score, the loser defends. Work through all 5 positions.', '10 reps, 2 from each position, rest between.', NULL, 'Correct explosive acceleration technique; use the body as a barrier to shield.', 'Pairs + GK', 3, NULL, 'Half a full sized pitch', NULL, NULL, 15.0, true, true, true, '14-18', 750),
  ('Wide race 2v2 attack from coach pass', 'one_v_one', 'opposed', NULL, 136, 136, NULL, 'Fernando Gaspar (China National Team)', 'Acceleration plus physical and mental speed in a 2v2.', 'Half pitch, two pairs (red attacker and yellow defender) out wide on each side, coach with balls in the centre circle, keeper in goal.', 'Coach plays wide to one side; the pair on that side race for it. The attacker can combine with his teammate from the other side to score quickly while the other defender tracks back.', '8 reps with recovery.', NULL, 'Freedom of choice; finish fast with the right option; defenders react quickly and work together.', '2v2 + GK', 5, 5, 'Half a full sized pitch', NULL, NULL, 15.0, true, true, true, '14-18', 760),
  ('Receive and score in 3 seconds', 'finishing', 'opposed', 'in_possession', 137, 137, NULL, 'Fernando Gaspar (China National Team)', 'Quick receiving and finishing in the box against a covering defender.', 'Penalty area: an attacker on the edge, 2 feeders with balls either side of the goal, 2 yellow defenders 4 yards to each side, keeper.', 'A feeder passes as the attacker comes forward; he must score within 3 seconds of receiving while one defender slides across to block, making a 1v1.', 'Score within 3 seconds. 6 reps per attacker; defenders alternate.', NULL, 'First touch out in front and away from the defender; defender closes fast and makes contact to stop or hinder the shot.', '1 attacker + 2 feeders + 2 defenders + GK', 6, NULL, 'Penalty area', NULL, NULL, 6.0, true, true, true, '14-18', 770),
  ('Dribble at speed 1v1, score in 5 seconds', 'one_v_one', 'opposed', 'in_possession', 138, 138, NULL, 'Fernando Gaspar (China National Team)', 'Attacking and defending 1v1 with a quick finish.', 'Half pitch, 3 starting positions (left, centre, right) with red attackers facing blue defenders at the box edge; keeper.', 'Attackers take turns, or the coach calls numbers at random. The attacker dribbles at pace and must score within 5 seconds while the defender tries to stop him.', 'Score within 5 seconds; 6 reps per attacker.', 'Work from players'' own positions or change zones; make it a 2-team competition.', 'Keep it close with feints and changes of direction; defender in side-on ''surfboard'' stance, body angled away from goal, matching the attacker''s speed.', '3 pairs + GK', NULL, NULL, 'Half a full sized pitch', NULL, NULL, 8.0, true, true, true, '14-18', 780),
  ('Footwork relay: hurdles, poles, rings', 'conditioning', 'unopposed', NULL, 139, 139, NULL, 'Fernando Gaspar (China National Team)', 'Coordination, foot speed and changing direction.', 'Two parallel 30-yard lanes, each with 2 hurdles, 2 poles, cones and speed rings.', 'Team race: jump the hurdles, weave the poles with two direction changes, run through two cones, hop alternate legs through the rings and run through the final cones.', '4 reps per player, at least 45 seconds rest between series; fastest team wins.', 'Add a ball and a mini goal at the end for a shot.', 'Hurdles sized for age; slow, bend knees and push off one foot to change direction; balance through the rings.', '2 teams', NULL, NULL, '30 yards long', 27.4, NULL, 12.0, false, false, false, '14-18', 790),
  ('Three-zone speed circuit with finishing', 'conditioning', 'opposed', NULL, 140, 140, NULL, 'Fernando Gaspar (China National Team)', 'Coordination, foot speed and quick reactions with agility.', 'Half pitch split into 3 zones with goals and keepers, hurdles, cones and speed ladders.', 'Zone 1: red and blue jump 3 hurdles then race for a ball, 1v1 to goal. Zone 2: mirror game, attacker sprints to one of 3 cones and defender copies; after 3 reps play a real 1v1 to goal. Zone 3: both run the ladder then one crosses for the other to finish.', NULL, NULL, NULL, NULL, NULL, NULL, 'Half a full sized pitch', NULL, NULL, 15.0, true, true, true, '14-18', 800),
  ('Hurdle jumps, switch to opposite wing, cross', 'combination', 'unopposed', 'in_possession', 141, 141, NULL, 'Fernando Gaspar (China National Team)', 'Speed, agility, vision and decision making in a crossing pattern.', 'Half pitch, 3 positions (centre and both wings) each with a hurdle, a yellow feeder with balls at the top of the box, keeper.', 'Players jump their hurdle 3 times (twice through with rest). Yellow passes to the centre player coming forward, then moves to one side; the centre player must switch the ball to the OPPOSITE wing. That winger crosses while the centre player and other winger attack the box.', 'Runs into the box no longer than 15 yards; 4 series, rotating roles with recovery.', 'Add 1 or 2 defenders for realism.', NULL, '3 + feeder + GK', 5, NULL, 'Half a full sized pitch', NULL, NULL, 8.0, true, true, true, '14-18', 810),
  ('Four-line pole circuit: dribble, pass right', 'passing_unopposed', 'unopposed', NULL, 142, 142, NULL, 'Fernando Gaspar (China National Team)', 'Conditioning plus ball control, passing and movement.', '4 lines of players set 5-10 yards apart in a cross shape around a circle, with lines of poles between each line and the centre.', 'Timed blocks: 4 min sprint to the middle and join the line on the right; 2 min slalom the poles with changes of pace and join the line on the left; 4 min with a ball per line, dribble through the poles, pass to the line on the right and run to the next position.', NULL, NULL, 'Everyone works at the same speed to keep the rhythm; slow, bend and push off one foot to change direction.', '4 lines', NULL, NULL, NULL, NULL, NULL, 10.0, false, false, false, '14-18', 820),
  ('Pass back then hurdle and sprint', 'warm_up', 'unopposed', NULL, 143, 143, NULL, 'Fernando Gaspar (China National Team)', 'Speed, agility and accurate passing; can serve as a warm-up.', 'Groups in lines with a keeper or support player 5-8 yards in front; 3 hurdles of low, medium and high height and a cone beyond.', 'Server plays in, player returns it, then jumps the 3 hurdles, sprints round the cone and back to the start. Three 3-minute blocks change the pass: ground pass returned first time, throw returned on the volley, throw headed back.', 'One-touch returns; 1 minute recovery between 3-minute series.', 'Use speed rings instead of or as well as hurdles.', NULL, 'Groups + GK or server', NULL, NULL, NULL, NULL, NULL, 12.0, false, true, false, '14-18', 830),
  ('4v4 plus 5 with shirt-tugging pressure', 'possession', 'overload', 'in_possession', 144, 144, NULL, 'Fernando Gaspar (China National Team)', 'Passing, keeping the ball, making space and support under physical pressure.', '20 x 20 yards, 4v4 inside, 5 blue support players for the team in possession (1 inside, 4 on the sides); orange players behind the outside supports tug their shirts for light resistance.', 'Team in possession aims for 10 passes using the supports. If defenders win it and make 5 passes, roles change; if they cannot stop 10 passes, restart with the same roles.', 'Max 3 passes to support players in any 10-pass sequence.', NULL, 'Control how hard the outside players are pulled; receive half-turned and aware; keep moving to use the overload.', '4v4+5 (+4 resistors)', 17, 17, '20 x 20 yards', 18.3, 18.3, 10.0, false, false, false, '14-18', 840),
  ('Two-sided agility race to shoot', 'conditioning', 'unopposed', NULL, 145, 145, NULL, 'Fernando Gaspar (China National Team)', 'Finishing after strength, agility and coordination work.', 'One goal with keeper; two sides: left has 1 hurdle, poles and 3 hurdles; right has speed rings, a pole and a cone gate; balls at the end of each course.', 'Two teams compete counting goals. Left: hurdle, pole slalom, 3 more hurdles, take a ball and shoot. Right: hop foot to foot through rings, round the outside pole, take a ball, dribble through cones and shoot.', 'Swap sides halfway, 5 minutes each.', NULL, 'Balanced body shape through the rings; height over hurdles with feet together.', '2 teams + GK', NULL, NULL, NULL, NULL, NULL, 10.0, true, true, true, '14-18', 850),
  ('Check away from marker, finish first time', 'finishing', 'opposed', 'in_possession', 146, 146, NULL, 'Fernando Gaspar (China National Team)', 'Checking away from a marker to receive and finish quickly.', 'Area about double the penalty box with a goal and keeper at each end; 8 numbered servers round the outside with 1-2 balls each; 1 attacker and 1 defender inside.', 'Coach calls a number and that server passes to the attacker, who checks away and sprints the other way to lose his marker and shoot first time at either goal.', 'Attacker works 30 seconds then swaps with the defender; then both swap with 2 servers.', NULL, 'Check away before moving to receive.', '1v1 + 8 servers + 2 GKs', 12, 12, 'About double the penalty area', NULL, NULL, 15.0, true, true, true, '14-18', 860),
  ('Hurdle jumps, dribble, shoot at called goal', 'finishing', 'unopposed', NULL, 147, 147, NULL, 'Fernando Gaspar (China National Team)', 'Jumping power, ball control and finishing.', 'One line of players, 3 hurdles, a yellow cone and 2 red cones, two coloured mini goals at the far end.', 'Jump the 3 hurdles feet together for height, take a ball, dribble round the yellow cone and through the red cones, then shoot into one of the mini goals.', 'A miss means a full sprint to a cone beside that goal. 8 minutes with 30 seconds rest every 2 minutes.', 'Coach calls the colour of goal to shoot at, for awareness.', 'Height over hurdles with feet together.', '1 line', NULL, NULL, NULL, NULL, NULL, 8.0, true, false, true, '14-18', 870),
  ('Ladder footwork into header and sprint', 'conditioning', 'unopposed', NULL, 148, 148, NULL, 'Fernando Gaspar (China National Team)', 'Coordination, explosive power and accurate heading.', '2 lines, each with a 4 m speed ladder and yellow cones 10 yards apart; a keeper serving at the end and a target cone off to the side.', 'Players run varied ladder patterns (e.g. 2 inside 1 outside touches), sprint out, head the keeper''s throw back, then turn and accelerate to the cone.', '2 minutes work, 30 seconds rest, 4 times.', 'Keep changing the ladder pattern.', 'Rhythm and quick feet on the ladder; both sprints at full speed.', '2 lines + 2 GKs', NULL, NULL, NULL, NULL, NULL, 10.0, false, true, false, '14-18', 880),
  ('Double-ladder footwork and sprint', 'conditioning', 'unopposed', NULL, 149, 149, NULL, 'Fernando Gaspar (China National Team)', 'Coordination, acceleration and explosive power.', '2 lines, each with two 4 m speed ladders joined end to end and a cone beyond.', 'Same idea as the ladder-and-header drill without the ball: players work through the long ladder with quick feet, then sprint to the cone.', '2 minutes work, 30 seconds rest, 4 times.', NULL, 'Quick feet plus endurance, as the ladder is twice as long.', '2 lines', NULL, NULL, NULL, NULL, NULL, 10.0, false, false, false, '14-18', 890),
  ('3v3 scoring through four cone gates', 'positional_game', 'opposed', 'in_possession', 150, 150, NULL, 'Fernando Gaspar (China National Team)', 'Creating space, movement off the ball and accurate passing.', 'Large area for the age group with 4 cone gates spread around; 3v3.', 'Score by passing through any gate to a teammate who controls it on the other side.', 'Unlimited touches; no more than 2 minutes without a break; always one more gate than teams so goals cannot simply be blocked.', NULL, 'High tempo; lose your marker and use the space; time and weight the pass through the gate to the run.', '3v3', 6, 6, 'Large area for the age/level', NULL, NULL, 10.0, false, false, true, '14-18', 900),
  ('Resisted sprint in pairs', 'conditioning', 'unopposed', NULL, 151, 151, NULL, 'Fernando Gaspar (China National Team)', 'Explosive power by sprinting against resistance.', 'Pairs; red cones 10 yards apart split into a 5-yard resistance zone and a 5-yard free sprint zone.', 'Runner drives forward for 5 yards while his partner holds him back, then is released to sprint flat out for 5 yards.', '10 reps, 5 each, swapping every time so nobody goes twice in a row.', NULL, 'Match the resistance to the age and level of the runner.', 'Pairs', 2, NULL, '10 yards', 9.1, NULL, 8.0, false, false, false, '14-18', 910),
  ('Dribble, stop, sprint, swap-ball channels', 'technical', 'unopposed', NULL, 152, 152, NULL, 'Fernando Gaspar (China National Team)', 'Ball control and speed on and off the ball.', '4 cones in a line: 5 yards, 10 yards, 5 yards apart; pairs start at opposite ends with a ball each.', 'Both dribble 5 yards in towards each other and stop the ball dead at the second cone, sprint 10 yards to the next cone, pick up the ball their partner left and dribble 5 yards to the end.', '3 series of 3 reps, 45 seconds rest between series.', NULL, 'Soft touches to keep the ball close.', 'Pairs', 2, NULL, '20 yards (5+10+5)', 18.3, NULL, 8.0, false, false, false, '14-18', 920),
  ('Fast-stop-slow-fast dribbling channels', 'technical', 'unopposed', NULL, 153, 153, NULL, 'Fernando Gaspar (China National Team)', 'Full control of the ball while changing pace: stop, start, slow, fast.', 'Same 5-10-5 yard cone line as the previous channel drill, pairs at opposite ends.', 'Dribble the first 5 yards fast and stop the ball dead, then dribble 10 yards slowly, then speed up for the final 5 yards.', '3 series of 3 reps, 45 seconds rest between series.', NULL, 'Dribble, stop and start with every part of the foot.', 'Pairs', 2, NULL, '20 yards (5+10+5)', 18.3, NULL, 8.0, false, false, false, '14-18', 930),
  ('One-touch passing diamond with hurdles', 'passing_unopposed', 'unopposed', NULL, 154, 154, NULL, 'Fernando Gaspar (China National Team)', 'Passing and receiving, open body shape and explosive jumping.', 'Area sized for the age group with several positions in a double-diamond shape, 2-3 players per position, hurdles at some positions, 2 balls starting diagonally opposite.', 'Balls travel round a set passing sequence; at hurdle positions the player jumps the hurdle before receiving and passing on to the next position.', 'Always 2 balls in play; one touch.', 'Reverse direction to use both feet; swap hurdles for rings or ladders.', 'Come to meet the ball half-turned in central spots; open up and receive on the back foot.', '2-3 per position', NULL, NULL, 'Suitable for age/level', NULL, NULL, 8.0, false, false, false, '14-18', 940),
  ('Slalom, one-two, round pole and shoot', 'combination', 'unopposed', 'in_possession', 155, 155, NULL, 'Fernando Gaspar (China National Team)', 'Quick changes of direction, combination play and shooting from the box edge.', 'Half pitch, 2 lines of players by halfway, cone slaloms, yellow feeders (teammate or coach) wide of the box with balls, a pole in the centre, 1-2 keepers.', 'Both lines slalom the cones, play a one-two with their yellow, then sprint in and round the central pole to receive the next pass and shoot from the edge of the box, both at the same time.', 'Two keepers if possible since both shoot together.', NULL, 'Time the last pass with the run round the pole; first touch away from the body, head over the ball; shoot first time where possible.', '2 lines + 2 feeders + GKs', NULL, NULL, 'Half a full sized pitch', NULL, NULL, 8.0, true, true, true, '14-18', 950),
  ('Hurdle start into 3v3 race for ball', 'small_sided_game', 'opposed', NULL, 156, 156, NULL, 'Fernando Gaspar (China National Team)', 'Agility, explosive power and speed in a small sided game.', '30 x 30 yards, 2 goals with keepers, 4 outfield players starting in the corners behind 2 hurdles each, ball in the centre.', 'Outfield players jump their 2 hurdles, race to the central ball and play 3v3 (2v2 plus keepers).', 'Games last 2 minutes; rest while walking back to the corners.', NULL, 'Feet together and height over hurdles; use feints to beat a man and attack the space behind.', '2v2 + 2 GKs (3v3)', 6, 6, '30 x 30 yards', 27.4, 27.4, 10.0, true, true, true, '14-18', 960),
  ('Five-group rotation with 3v3 attack', 'conditioning', 'opposed', NULL, 157, 157, NULL, 'Fernando Gaspar (China National Team)', 'Agility, speed, strength plus attacking and defending in a continuous circuit.', 'More than half a pitch split into zones, keeper in goal, players in groups of 3, hurdles on the flank and medicine balls.', 'Five 15-second tasks rotate: group 1 attacks in combination to score in the box, group 2 defends that attack, group 3 sprints, jumps 3 hurdles and sprints to halfway, group 4 rests, group 5 does medicine-ball strength work.', 'Each task lasts 15 seconds.', NULL, 'Pick your own strength exercise if no medicine balls; attackers run into the space behind defenders.', '5 groups of 3 + GK', 16, 16, 'More than half a full sized pitch', NULL, NULL, 10.0, true, true, true, '14-18', 970),
  ('Sprint-brake-skip cones into one-two', 'conditioning', 'unopposed', NULL, 158, 158, NULL, 'Fernando Gaspar (China National Team)', 'Speed, acceleration, deceleration, coordination and quick feet.', '2 groups, each facing 3 cones 5 yards apart, with a yellow teammate with a ball beyond the last cone.', 'Sprint and brake at the first cone, sprint between the next cones braking and doing linear skips past each, then play a one-two with the yellow and jog back to the start.', '30 seconds break every 2.5 minutes.', NULL, 'Shorten steps and bend knees to slow down; keep intensity high.', '2 groups + 2 servers', NULL, NULL, 'Cones 5 yards apart', NULL, NULL, 10.0, false, false, false, '14-18', 980),
  ('4v1 one-touch rondo in small squares', 'rondo', 'overload', 'in_possession', 159, 159, NULL, 'Fernando Gaspar (China National Team)', 'Technical basics of keeping the ball at high intensity.', '4 groups, each with a 6 x 6 yard square: 4 players outside, 1 defender inside.', 'Outside players try to make 10 passes; if the defender wins it, the player who lost it goes in the middle.', 'One touch. Change the defender if he has been in too long.', NULL, 'Support angles so everyone has 2 easy options; let the ball run across the body; pass with the back foot.', '4v1 x 4 groups', 5, 20, '6 x 6 yards', 5.5, 5.5, 15.0, false, false, false, '14-18', 990),
  ('Three-zone rotation: run, pass, dribble', 'conditioning', 'unopposed', NULL, 161, 161, NULL, 'Fernando Gaspar (China National Team)', 'Acceleration, speed, passing, movement and ball control in a conditioning circuit.', 'Full pitch, 3 groups of 6-8 players in 3 zones: A round the outside of the pitch, B and C in the two central halves.', 'Zone A: 4 pairs run from the corners at varied pace (sprints, slow jogs, forwards, backwards, sideways, through poles). Zone B: pairs pass into space for the partner to run onto. Zone C: each player dribbles with different turns and feints.', 'Zone B 2-3 touches. Rotate zones every 5 minutes. Target heart rate 140-160 bpm.', NULL, 'Keep a steady rhythm.', '3 groups of 6-8', 18, 24, 'Full sized pitch', NULL, NULL, 15.0, false, false, false, '14-18', 1000),
  ('Outside runners one-two with inside joggers', 'conditioning', 'unopposed', NULL, 162, 162, NULL, 'Fernando Gaspar (China National Team)', 'Acceleration, deceleration and one-two combinations.', 'Same full-pitch layout as the previous circuit: 8 players with a ball each on the outside track, 8 on the inside rectangle.', 'Outside players run with the ball, quick over short stretches and controlled over long ones; inside players run at moderate pace the opposite way and play one-twos with them.', 'Change direction after 1.5 minutes; swap roles every 3 minutes with 1 minute rest. Heart rate 130-160 bpm.', NULL, NULL, '8 + 8', 16, 16, 'Full sized pitch', NULL, NULL, 15.0, false, false, false, '14-18', 1010),
  ('11-a-side shadow possession with laps', 'passing_unopposed', 'unopposed', 'in_possession', 163, 163, NULL, 'Fernando Gaspar (China National Team)', 'Positional movement and passing in possession, combined with lap running.', 'Full pitch, one team of 11 (or 10) in each half in their match positions, keeper starts with the ball.', 'Each team keeps the ball in its own half, staying compact, moving constantly and switching play. On the coach''s whistle after about 3 minutes everyone runs 2 laps of the pitch from a cone, then resumes.', 'Max 3 touches. 2 series of 12-15 minutes; heart rate 160-175 bpm.', 'Rotate players'' positions.', 'Coach sets the tempo and directs the exercise.', '2 teams of 10-11', 20, 22, 'Full sized pitch', NULL, NULL, 30.0, false, true, false, '14-18', 1020),
  ('6v6 multi-goal game with running team', 'conditioning', 'opposed', NULL, 164, 164, NULL, 'Fernando Gaspar (China National Team)', 'Conditioning through interval running and a small sided game.', 'Full pitch, 3 teams of 6 and a neutral keeper; central zone with 4 small 2-yard goals and 1 large goal.', 'Two teams play 6v6 trying to score in the opponents'' small goals or either side of the large goal by shooting or dribbling through. The third team runs laps of the pitch at varied pace (sprint the width, jog the length).', 'Unlimited touches. Rotate teams every 5 minutes. Heart rate 160-180 bpm.', NULL, NULL, '3 teams of 6 + neutral GK', 19, 19, 'Full sized pitch', NULL, NULL, 30.0, true, true, true, '14-18', 1030),
  ('Six-player set-and-switch passing circuit', 'passing_unopposed', 'unopposed', NULL, 165, 165, NULL, 'Fernando Gaspar (China National Team)', 'Speed, weight and timing of ground and lofted passes and of movement, plus conditioning.', '20 x 20 yards, 6 players at positions A-F; A and C start with a ball each.', 'A and C play short to B and D, who set first time into space for them to run onto. A and C then hit diagonal passes to E and F and follow with curved runs; E and F dribble back to the start positions now held by B and D, and everyone rotates for the next round.', 'Set pass first time. 3-5 series with 1-2 minutes rest; heart rate 160-180 bpm.', NULL, NULL, '6 players', 6, 6, '20 x 20 yards', 18.3, 18.3, 15.0, false, false, false, '14-18', 1040),
  ('Agility stations, sprint and jog intervals', 'conditioning', 'unopposed', NULL, 166, 166, NULL, 'Fernando Gaspar (China National Team)', 'Agility, speed, acceleration and coordination in interval work.', 'Full pitch, 2 groups of 8-9; reds in threes at 3 start cones with hurdles, poles or rings; yellows in pairs in a passing grid.', 'Reds do 6 feet-together hurdle jumps, a fast pole slalom or 8 lateral bounds, then sprint 35-50 yards for 10 seconds to the next cone and slow-jog about 100 yards back round to the start. Yellows meanwhile pass in pairs.', 'Reds 3 full series without rest; yellows 1-2 touches; groups swap after the 3 series. Heart rate 160-180 bpm.', NULL, NULL, '2 groups of 8-9', 16, 18, 'Full sized pitch', NULL, NULL, 20.0, false, false, false, '14-18', 1050),
  ('Corner technique zones around 6v2 rondo', 'conditioning', 'overload', NULL, 167, 167, NULL, 'Fernando Gaspar (China National Team)', 'Conditioning with short sprints and technical actions.', '2 groups of 8; four 5 x 5 yard corner zones and a 10 x 10 yard central zone.', 'Red pairs do 20-30 seconds of technique in each corner (two-footed passing, ball mastery touches, juggling in pairs, dribbling with feints) then sprint 5-10 seconds to the next zone. Yellows play 6v2 keep-ball in the centre; after 3 series the groups swap so the reds recover in the rondo.', '3 series with 1 minute rest; change the 2 defenders often. Heart rate 160-180 bpm.', NULL, 'Insist on technical quality.', '2 groups of 8', 16, 16, '5 x 5 yard corners, 10 x 10 yard centre', NULL, NULL, 20.0, false, false, false, '14-18', 1060),
  ('Team shape passing with sprints to lines', 'conditioning', 'unopposed', 'in_possession', 168, 168, NULL, 'Fernando Gaspar (China National Team)', 'Conditioning combined with team shape and passing.', 'Full pitch, players in match positions (e.g. 4-4-2) in one half; cone lines in the other half for defence, midfield and attack, plus one for keepers.', 'Players pass along and between their lines at moderate pace. On the coach''s signal each sprints at about 80% to his unit''s line in the other half and back (about 15 seconds, 70-75 yards), then resumes passing.', '20-30 seconds rest after each run; 3 reps per series, 2 series with 2 minutes rest. Heart rate 160-185 bpm.', 'Vary the skills and technical actions in the passing.', NULL, 'Full team', NULL, NULL, 'Full sized pitch', NULL, NULL, 25.0, false, true, false, '14-18', 1070),
  ('8v8 dribble-through end zones with sprints', 'conditioning', 'opposed', NULL, 169, 169, NULL, 'Fernando Gaspar (China National Team)', 'Speed, acceleration and endurance.', '40 x 25 yards with pole gates on each end line; behind the area 3 cones 15 yards apart for sprints.', 'Two teams of 8 (or 9) play; a goal is scored by dribbling through the poles in the opposition half, and the scorer''s team keeps the ball. About halfway (5 minutes) both teams do 3-5 build-up sprints over 30 yards (70% to 100% speed) with 30 seconds rest, then another set, before playing the second half.', 'Unlimited touches. Heart rate 150-175 bpm; recover to 120 bpm between.', NULL, NULL, '8v8 or 9v9', 16, 18, '40 x 25 yards', 36.6, 22.9, 30.0, false, false, true, '14-18', 1080),
  ('Three-zone keep-ball with keeper supports', 'possession', 'opposed', 'in_possession', 170, 170, NULL, 'Fernando Gaspar (China National Team)', 'Technical actions to keep the ball while building conditioning.', '25 x 20 yards split into 3 numbered zones; 2 teams of 6; 2 neutral keepers behind the zones who may only use their feet; coach with balls.', 'Teams keep the ball and move it round the zones, using the keepers as support. The coach decides whether play uses 1, 2 or all 3 zones and feeds a new ball straight away when it goes out. Count consecutive passes.', 'Unlimited or 2-3 touches as set by the coach. 3 x 5 minutes, 2 minutes rest; heart rate 160-180 bpm.', 'Change the number of zones in use and the touch limit.', NULL, '6v6 + 2 neutral GKs', 14, 14, '25 x 20 yards', 22.9, 18.3, 25.0, false, true, false, '14-18', 1090),
  ('6v6 rotating teams, all past halfway', 'small_sided_game', 'opposed', 'in_possession', 171, 171, NULL, 'Fernando Gaspar (China National Team)', 'Conditioning in a continuous technical small sided game with fast support play.', '50 x 40 yards, two goals with keepers, 3 teams of 5; the resting team waits on the sidelines; coach feeds balls.', 'Two teams play 6v6 with keepers; the coach plays a new ball in whenever it goes out. Teams rotate every 2 minutes so each plays 4 minutes and rests 2.', 'Limited touches in the defending half, free in the attacking half. A goal only counts if the whole attacking team is over halfway; it counts double if an opponent is still in the other half. Games of 6 minutes, 2 minutes rest, 4 games; heart rate 165-180 bpm.', NULL, NULL, '3 teams of 5 + 2 GKs', 17, 17, '50 x 40 yards', 45.7, 36.6, 35.0, true, true, true, '14-18', 1100),
  ('4v4 inside with 4 outside supports each', 'small_sided_game', 'opposed', 'in_possession', 172, 172, NULL, 'Fernando Gaspar (China National Team)', 'Aerobic conditioning in a continuous technical small sided game.', '50 x 40 yards, two goals with keepers, 2 teams of 8: 4v4 inside, each team with 4 more players on the outside, spare balls by the goals.', 'Teams try to score using their outside players. When the ball goes out, the keeper of the team in possession restarts quickly.', 'Inside players unlimited touches; outside players and keepers one touch. 4 x 4-minute games, 1 minute rest, roles swapped every game. Heart rate 170-190 bpm.', NULL, NULL, '8v8 (4v4+4+4) + 2 GKs', 18, 18, '50 x 40 yards', 45.7, 36.6, 20.0, true, true, true, '14-18', 1110)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'advanced-spanish-academy-coaching-120-technical-tactical-and-conditioning-practi') b;
INSERT INTO schema_migrations (filename) VALUES ('2402-exercises-book-advanced-spanish-academy-coaching-120-technical-tactical-and.sql') ON CONFLICT DO NOTHING;
COMMIT;
